package com.nigson.integration.notification;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.transaction.support.TransactionTemplate;
import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
import tools.jackson.databind.node.ObjectNode;
import com.nigson.integration.platform.*;
import com.nigson.integration.providers.TwilioAccount;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.ProviderHttp;
import static org.assertj.core.api.Assertions.*;
class VerificationIntakePersistenceTest {
 private static final AtomicInteger REVISIONS=new AtomicInteger(100);
 JdbcTemplate jdbc;DataSourceTransactionManager manager;PlatformStore store;AuditWriter audit;VerificationRequestedHandler handler;Clock clock;int revision;String consumer="verification-test-"+UUID.randomUUID();UUID generation=UUID.randomUUID();final String account="AC"+"0".repeat(32),service="MG"+"1".repeat(32);UUID sms,whatsapp;
 @BeforeEach void setup(){String url=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(url!=null,"native integration-owned PostgreSQL required");if(!url.matches("jdbc:postgresql://127.0.0.1:[0-9]+/nigson"))throw new IllegalArgumentException("LOCAL_DB_REQUIRED");jdbc=new JdbcTemplate(new DriverManagerDataSource(url+"?currentSchema=integration","nigson_integration_app","mock-integration-runtime"));manager=new DataSourceTransactionManager(jdbc.getDataSource());clock=Clock.systemUTC();var metrics=new SimpleMeterRegistry();store=new PlatformStore(jdbc,manager,clock,metrics);audit=new AuditWriter(jdbc,clock,metrics);revision=REVISIONS.incrementAndGet();sms=template("SMS");whatsapp=template("WHATSAPP");handler=handler(audit,ProviderHttp.Mode.MOCK,revision,"en-NG",account,service);}
 VerificationRequestedHandler handler(AuditWriter audit,ProviderHttp.Mode mode,int revision,String locale,String account,String service){return new VerificationRequestedHandler(audit,clock,"test",mode,locale,Map.of("SMS",revision,"WHATSAPP",revision),account,service,generation);}
 static tools.jackson.databind.JsonNode schema(){return EventCodec.JSON.readTree("{\"type\":\"object\",\"additionalProperties\":false,\"properties\":{\"code\":{\"type\":\"string\",\"maxLength\":6},\"expiresAt\":{\"type\":\"string\",\"maxLength\":40}},\"required\":[\"code\",\"expiresAt\"]}");}
 UUID template(String channel){UUID id=UUID.randomUUID();jdbc.update("INSERT INTO integration.notification_template(id,created_by,updated_by,code,revision,locale,channel,body,classification,active,provider_template_id,variables_schema) VALUES (?,'test','test','CONTACT_VERIFICATION',?,'en-NG',?,'Synthetic code {{code}}, expiry {{expiresAt}}','TRANSACTIONAL',true,?,?::jsonb)",id,revision,channel,channel.equals("WHATSAPP")?"HX"+"2".repeat(32):null,EventCodec.JSON.writeValueAsString(schema()));return id;}
 ObjectNode event(String channel){var e=EventCodec.JSON.createObjectNode();UUID destination=UUID.randomUUID(),verification=UUID.randomUUID();e.put("event_id",UUID.randomUUID().toString()).put("event_type","communication.verification.requested.v1").put("schema_version",1).put("producer","experience").put("occurred_at",clock.instant().toString()).put("aggregate_id",destination.toString()).put("aggregate_version",0).put("correlation_id",UUID.randomUUID().toString());e.putNull("organization_id");e.putNull("traceparent");e.set("payload",EventCodec.JSON.valueToTree(Map.of("verification_id",verification,"destination_id",destination,"channel",channel)));return e;}
 UUID job(ObjectNode event){return VerificationRequestedHandler.job(UUID.fromString(event.path("payload").path("verification_id").asString()));}
 boolean consume(ObjectNode event){return store.consume(consumer,EventCodec.JSON.writeValueAsString(event),1,handler::handle);}
 @Test void smsAndWhatsappPersistPairedFrozenIntentWithNoProviderSuccess(){for(String channel:List.of("SMS","WHATSAPP")){var event=event(channel);assertThat(consume(event)).isTrue();UUID id=job(event);var job=jdbc.queryForMap("SELECT * FROM integration.notification_job WHERE id=?",id);assertThat(job.get("state")).isEqualTo("PENDING");assertThat(job.get("attempt_count")).isEqualTo(0);assertThat(job.get("channel")).isEqualTo(channel);assertThat(job.get("provider_mode")).isEqualTo("MOCK");assertThat(job.get("provider_reference")).isNull();var intent=jdbc.queryForMap("SELECT * FROM integration.notification_dispatch WHERE id=?",id);assertThat(intent.get("stage")).isEqualTo("INTENT");assertThat(intent.get("generation")).isEqualTo(generation);assertThat(intent.get("account_hash")).isEqualTo(TwilioAccount.fingerprint(ProviderHttp.Mode.MOCK,account,service));assertThat(intent.get("request_hash")).isNull();assertThat(intent.get("provider_message_id")).isNull();var snapshot=EventCodec.JSON.readTree(intent.get("template_snapshot").toString());assertThat(intent.get("template_hash")).isEqualTo(EventCodec.hash(snapshot));assertThat(snapshot.path("locale").asString()).isEqualTo("en-NG");assertThat(snapshot.path("body").asString()).contains("{{code}}");assertThat(snapshot.propertyNames()).doesNotContain("phone","renderedCode","address","recipient");assertThat(snapshot.path("code").asString()).isEqualTo("CONTACT_VERIFICATION");assertThat(jdbc.queryForObject("SELECT count(*) FROM integration.audit_record WHERE resource_id=?",Integer.class,id)).isEqualTo(1);assertThat(consume(event)).isFalse();}}
 @Test void twelveSemanticEventsCreateOneJobIntentAndAudit()throws Exception{var original=event("SMS");try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var start=new CountDownLatch(1);var futures=new ArrayList<Future<Boolean>>();for(int i=0;i<12;i++){var event=original.deepCopy().put("event_id",UUID.randomUUID().toString()).put("aggregate_version",i);futures.add(pool.submit(()->{start.await();return consume(event);}));}start.countDown();for(var future:futures)assertThat(future.get(15,TimeUnit.SECONDS)).isTrue();}UUID id=job(original);assertThat(jdbc.queryForObject("SELECT count(*) FROM integration.notification_job WHERE id=?",Integer.class,id)).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT count(*) FROM integration.notification_dispatch WHERE id=?",Integer.class,id)).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT count(*) FROM integration.audit_record WHERE resource_id=?",Integer.class,id)).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT count(*) FROM integration.processed_event WHERE consumer=?",Integer.class,consumer)).isEqualTo(12);}
 @Test void configurationRotationAndReplayPreserveOriginalUnknownTruthAndSnapshots(){var event=event("WHATSAPP");consume(event);UUID id=job(event);jdbc.update("UPDATE integration.notification_job SET state='UNKNOWN',attempt_count=3,provider_reference=? WHERE id=?","SM"+"3".repeat(32),id);jdbc.update("UPDATE integration.notification_dispatch SET stage='UNKNOWN',lease_until=now()+interval '1 hour',provider_message_id=? WHERE id=?","SM"+"3".repeat(32),id);var before=jdbc.queryForMap("SELECT * FROM integration.notification_dispatch WHERE id=?",id);var rotated=handler(audit,ProviderHttp.Mode.TEST,revision+1000,"fr-NG","AC"+"4".repeat(32),"MG"+"5".repeat(32));var duplicate=event.deepCopy().put("event_id",UUID.randomUUID().toString());assertThat(store.consume(consumer,EventCodec.JSON.writeValueAsString(duplicate),1,rotated::handle)).isTrue();assertThat(jdbc.queryForMap("SELECT * FROM integration.notification_dispatch WHERE id=?",id)).isEqualTo(before);var job=jdbc.queryForMap("SELECT state,attempt_count,provider_mode FROM integration.notification_job WHERE id=?",id);assertThat(job.get("state")).isEqualTo("UNKNOWN");assertThat(job.get("attempt_count")).isEqualTo(3);assertThat(job.get("provider_mode")).isEqualTo("MOCK");}
 @Test void reboundDestinationOrChannelCannotManufactureAnotherJob(){var original=event("SMS");consume(original);for(boolean changeChannel:List.of(false,true)){var changed=original.deepCopy().put("event_id",UUID.randomUUID().toString());var payload=(ObjectNode)changed.path("payload");if(changeChannel)payload.put("channel","WHATSAPP");else{String destination=UUID.randomUUID().toString();payload.put("destination_id",destination);changed.put("aggregate_id",destination);}assertThatThrownBy(()->consume(changed)).isInstanceOf(Problem.Failure.class);assertThat(jdbc.queryForObject("SELECT count(*) FROM integration.processed_event WHERE consumer=? AND event_id=?",Integer.class,consumer,UUID.fromString(changed.path("event_id").asString()))).isZero();}assertThat(jdbc.queryForObject("SELECT count(*) FROM integration.notification_job WHERE id=?",Integer.class,job(original))).isEqualTo(1);}
 @Test void missingPairedIntentAfterPartialRestoreRejectsInsteadOfBackfilling(){var event=event("SMS");consume(event);jdbc.update("DELETE FROM integration.notification_dispatch WHERE id=?",job(event));var duplicate=event.deepCopy().put("event_id",UUID.randomUUID().toString());assertThatThrownBy(()->consume(duplicate)).isInstanceOfSatisfying(Problem.Failure.class,f->assertThat(f.code).isEqualTo(ProblemCode.PROVIDER_OUTCOME_UNKNOWN));assertThat(jdbc.queryForObject("SELECT count(*) FROM integration.notification_dispatch WHERE id=?",Integer.class,job(event))).isZero();}
 @Test void missingInactiveOrUnsafeTemplateDoesNotAcknowledgeWork(){for(String channel:List.of("SMS","WHATSAPP")){UUID template=channel.equals("SMS")?sms:whatsapp;jdbc.update("UPDATE integration.notification_template SET active=false WHERE id=?",template);var event=event(channel);assertThatThrownBy(()->consume(event)).isInstanceOf(Problem.Failure.class);assertThat(jdbc.queryForObject("SELECT count(*) FROM integration.notification_job WHERE id=?",Integer.class,job(event))).isZero();jdbc.update("UPDATE integration.notification_template SET active=true,body='{{#if code}}{{code}}{{/if}}' WHERE id=?",template);assertThatThrownBy(()->consume(event)).isInstanceOf(Problem.Failure.class);assertThat(jdbc.queryForObject("SELECT count(*) FROM integration.processed_event WHERE consumer=?",Integer.class,consumer)).isZero();}}
 @Test void auditFailureRollsBackIntentJobAndInbox(){var failing=new JdbcTemplate(jdbc.getDataSource()){@Override public int update(String sql,Object... args){throw new org.springframework.dao.PermissionDeniedDataAccessException("SYNTHETIC_AUDIT_DENIAL",null);}};var failed=handler(new AuditWriter(failing,clock,new SimpleMeterRegistry()),ProviderHttp.Mode.MOCK,revision,"en-NG",account,service);var event=event("SMS");assertThatThrownBy(()->store.consume(consumer,EventCodec.JSON.writeValueAsString(event),1,failed::handle)).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThat(jdbc.queryForObject("SELECT count(*) FROM integration.notification_job WHERE id=?",Integer.class,job(event))).isZero();assertThat(jdbc.queryForObject("SELECT count(*) FROM integration.notification_dispatch WHERE id=?",Integer.class,job(event))).isZero();assertThat(jdbc.queryForObject("SELECT count(*) FROM integration.processed_event WHERE consumer=?",Integer.class,consumer)).isZero();}
 @Test void testTransportKeepsSandboxStateAndAccountIdentityUsesActualTestMode(){handler=handler(audit,ProviderHttp.Mode.TEST,revision,"en-NG",account,service);var event=event("SMS");consume(event);assertThat(jdbc.queryForObject("SELECT provider_mode FROM integration.notification_job WHERE id=?",String.class,job(event))).isEqualTo("SANDBOX");assertThat(jdbc.queryForObject("SELECT account_hash FROM integration.notification_dispatch WHERE id=?",String.class,job(event))).isEqualTo(TwilioAccount.fingerprint(ProviderHttp.Mode.TEST,account,service));assertThatThrownBy(()->new VerificationRequestedHandler(audit,clock,"prod",ProviderHttp.Mode.MOCK,"en-NG",Map.of("SMS",revision,"WHATSAPP",revision),account,service,generation)).isInstanceOf(IllegalArgumentException.class);}
 @Test void rejectsInvocationOutsideTransactionAndMismatchedAggregate(){var event=event("SMS");assertThatThrownBy(()->handler.handle(jdbc,event)).isInstanceOf(IllegalStateException.class);event.put("aggregate_id",UUID.randomUUID().toString());assertThatThrownBy(()->consume(event)).isInstanceOf(Problem.Failure.class);assertThat(jdbc.queryForObject("SELECT count(*) FROM integration.processed_event WHERE consumer=?",Integer.class,consumer)).isZero();}
 @Test void realSnsSqsRedeliveryOnlyAcknowledgesCommittedPairedWork()throws Exception{
  String endpoint=System.getenv("NIGSON_TEST_EVENT_ENDPOINT");Assumptions.assumeTrue(endpoint!=null,"isolated LocalStack SNS/SQS required");if(!endpoint.matches("http://127.0.0.1:[0-9]+"))throw new IllegalArgumentException("LOCAL_AWS_REQUIRED");var credentials=software.amazon.awssdk.auth.credentials.StaticCredentialsProvider.create(software.amazon.awssdk.auth.credentials.AwsBasicCredentials.create("test","test"));
  try(var sns=software.amazon.awssdk.services.sns.SnsClient.builder().endpointOverride(java.net.URI.create(endpoint)).region(software.amazon.awssdk.regions.Region.US_EAST_1).credentialsProvider(credentials).build();var sqs=software.amazon.awssdk.services.sqs.SqsClient.builder().endpointOverride(java.net.URI.create(endpoint)).region(software.amazon.awssdk.regions.Region.US_EAST_1).credentialsProvider(credentials).build()){
   String suffix=UUID.randomUUID().toString(),topic=sns.createTopic(r->r.name("verification-"+suffix)).topicArn(),queue=sqs.createQueue(r->r.queueName("verification-"+suffix)).queueUrl();
   try{String arn=sqs.getQueueAttributes(r->r.queueUrl(queue).attributeNames(software.amazon.awssdk.services.sqs.model.QueueAttributeName.QUEUE_ARN)).attributes().get(software.amazon.awssdk.services.sqs.model.QueueAttributeName.QUEUE_ARN);sqs.setQueueAttributes(r->r.queueUrl(queue).attributes(Map.of(software.amazon.awssdk.services.sqs.model.QueueAttributeName.POLICY,EventCodec.JSON.writeValueAsString(Map.of("Version","2012-10-17","Statement",List.of(Map.of("Effect","Allow","Principal",Map.of("Service","sns.amazonaws.com"),"Action","sqs:SendMessage","Resource",arn,"Condition",Map.of("ArnEquals",Map.of("aws:SourceArn",topic)))))))));sns.subscribe(r->r.topicArn(topic).protocol("sqs").endpoint(arn).attributes(Map.of("RawMessageDelivery","true","FilterPolicy",EventCodec.JSON.writeValueAsString(Map.of("event_type",List.of(handler.eventType()),"producer",List.of("experience"))))));var event=event("SMS");String body=EventCodec.JSON.writeValueAsString(event);var attrs=Map.of("event_type",software.amazon.awssdk.services.sns.model.MessageAttributeValue.builder().dataType("String").stringValue(handler.eventType()).build(),"producer",software.amazon.awssdk.services.sns.model.MessageAttributeValue.builder().dataType("String").stringValue("experience").build());sns.publish(r->r.topicArn(topic).message(body).messageAttributes(attrs));var received=sqs.receiveMessage(r->r.queueUrl(queue).waitTimeSeconds(3).visibilityTimeout(30)).messages();assertThat(received).hasSize(1);
    var failing=new JdbcTemplate(jdbc.getDataSource()){@Override public int update(String sql,Object... args){throw new org.springframework.dao.PermissionDeniedDataAccessException("SYNTHETIC_AUDIT_DENIAL",null);}};var failed=handler(new AuditWriter(failing,clock,new SimpleMeterRegistry()),ProviderHttp.Mode.MOCK,revision,"en-NG",account,service);
    try(var pump=pump(endpoint,topic,queue,failed)){assertThat(pump.process(received.getFirst())).isFalse();assertThat(jdbc.queryForObject("SELECT count(*) FROM integration.notification_job WHERE id=?",Integer.class,job(event))).isZero();sqs.changeMessageVisibility(r->r.queueUrl(queue).receiptHandle(received.getFirst().receiptHandle()).visibilityTimeout(0));var redelivered=sqs.receiveMessage(r->r.queueUrl(queue).waitTimeSeconds(3).visibilityTimeout(30)).messages();assertThat(redelivered).hasSize(1);try(var success=pump(endpoint,topic,queue,handler)){assertThat(success.process(redelivered.getFirst())).isTrue();sns.publish(r->r.topicArn(topic).message(body).messageAttributes(attrs));var duplicate=sqs.receiveMessage(r->r.queueUrl(queue).waitTimeSeconds(3).visibilityTimeout(30)).messages();assertThat(duplicate).hasSize(1);assertThat(success.process(duplicate.getFirst())).isTrue();assertThat(jdbc.queryForObject("SELECT count(*) FROM integration.notification_job WHERE id=?",Integer.class,job(event))).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT count(*) FROM integration.notification_dispatch WHERE id=?",Integer.class,job(event))).isEqualTo(1);}}
   }finally{sqs.deleteQueue(r->r.queueUrl(queue));sns.deleteTopic(r->r.topicArn(topic));}
  }
 }
 EventPump pump(String endpoint,String topic,String queue,VerificationRequestedHandler selected){var credentials=software.amazon.awssdk.auth.credentials.StaticCredentialsProvider.create(software.amazon.awssdk.auth.credentials.AwsBasicCredentials.create("test","test"));var sns=software.amazon.awssdk.services.sns.SnsClient.builder().endpointOverride(java.net.URI.create(endpoint)).region(software.amazon.awssdk.regions.Region.US_EAST_1).credentialsProvider(credentials).build();var sqs=software.amazon.awssdk.services.sqs.SqsClient.builder().endpointOverride(java.net.URI.create(endpoint)).region(software.amazon.awssdk.regions.Region.US_EAST_1).credentialsProvider(credentials).build();return new EventPump(store,sns,sqs,topic,queue,queue,1,Map.of(selected.eventType(),selected::handle));}
 @Test void enabledApplicationRegistersConcreteIntakeAndDefaultOffNeverInstallsAcknowledgement()throws Exception{
  var keys=java.security.KeyPairGenerator.getInstance("EC");keys.initialize(new java.security.spec.ECGenParameterSpec("secp256r1"));String encoded=Base64.getEncoder().encodeToString(keys.generateKeyPair().getPublic().getEncoded());var properties=new HashMap<String,Object>();properties.put("APP_ENV","test");properties.put("NIGSON_SECURITY_ENABLED","true");properties.put("NIGSON_PROVIDERS_ENABLED","false");properties.put("NIGSON_EVENTS_ENABLED","false");properties.put("NIGSON_JDBC_URL",System.getenv("NIGSON_TEST_JDBC_URL")+"?currentSchema=integration");properties.put("NIGSON_DB_USER","nigson_integration_app");properties.put("NIGSON_DB_PASSWORD","mock-integration-runtime");properties.put("NIGSON_OIDC_ISSUER","http://127.0.0.1:9/realms/offline");properties.put("NIGSON_OIDC_JWKS","http://127.0.0.1:9/realms/offline/protocol/openid-connect/certs");properties.put("NIGSON_PRIVATE_PEER_CIDRS","127.0.0.1/32");properties.put("NIGSON_ACTOR_PUBLIC_KEYS",EventCodec.JSON.writeValueAsString(Map.of("active",encoded)));properties.put("server.port","0");properties.put("logging.level.root","WARN");
  try(var app=new org.springframework.boot.builder.SpringApplicationBuilder(com.nigson.integration.IntegrationApplication.class).properties(properties).run()){assertThat(app.getBeansOfType(EventHandler.class)).isEmpty();}
  properties.put("NIGSON_MESSAGING_VERIFICATION_INTAKE_ENABLED","true");properties.put("TWILIO_MODE","MOCK");properties.put("TWILIO_ACCOUNT_SID",account);properties.put("TWILIO_MESSAGING_SERVICE_SID",service);properties.put("NIGSON_MESSAGING_CREATION_GENERATION",generation.toString());properties.put("NIGSON_MESSAGING_LOCALE","en-NG");properties.put("NIGSON_MESSAGING_VERIFICATION_SMS_REVISION",revision);properties.put("NIGSON_MESSAGING_VERIFICATION_WHATSAPP_REVISION",revision);
  try(var app=new org.springframework.boot.builder.SpringApplicationBuilder(com.nigson.integration.IntegrationApplication.class).properties(properties).run()){assertThat(app.getBeansOfType(EventHandler.class)).containsOnlyKeys("verificationRequestedHandler");var actual=app.getBean(VerificationRequestedHandler.class);var event=event("SMS");assertThat(app.getBean(PlatformStore.class).consume(consumer,EventCodec.JSON.writeValueAsString(event),1,actual::handle)).isTrue();assertThat(jdbc.queryForObject("SELECT stage FROM integration.notification_dispatch WHERE id=?",String.class,job(event))).isEqualTo("INTENT");}
 }
}
